:root {
  --bg-sheet: #1e1a2e;
  --bg-header: #2c2547;
  --bg-stat: #2a2240;
  --bg-vital-hp: #5c1f2e;
  --bg-vital-ac: #1f3a5c;
  --bg-vital-speed: #1f4a30;
  --bg-vital-prof: #3a2c10;
  --bg-skill: #252040;
  --bg-skill-active: #3b2f6e;
  --bg-trait: #2c2547;
  --accent-gold: #e0a830;
  --accent-purple: #a87de8;
  --accent-teal: #4ec9b0;
  --text-primary: #f0eaff;
  --text-muted: #9989bb;
  --text-mod: #4ec9b0;
  --border-subtle: #3d3460;
  --badge-race-bg: #3b2f6e;
  --badge-race-text: #c9aaff;
  --badge-align-bg: #2c4a2c;
  --badge-align-text: #7ed68a;
}

.char-sheet {
  background: var(--bg-sheet);
  border: 2px solid var(--border-subtle);
  border-radius: 10px;
  width: 472px;
  overflow: hidden;
}

.sheet-header {
  background: var(--bg-header);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 10px;
  border-bottom: 2px solid var(--accent-gold);
}

.char-identity {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.char-name {
  font-size: 15px;
  font-weight: 700;
  color: var(--accent-gold);
}

.char-class {
  font-size: 10px;
  color: var(--text-muted);
  font-weight: 500;
}

.char-badges {
  display: flex;
  gap: 5px;
}

.badge {
  font-size: 10px;
  font-weight: 600;
  padding: 2px 7px;
  border-radius: 20px;
}

.badge.race {
  background: var(--badge-race-bg);
  color: var(--badge-race-text);
  border: 1px solid var(--accent-purple);
}

.badge.align {
  background: var(--badge-align-bg);
  color: var(--badge-align-text);
  border: 1px solid var(--badge-align-text);
}

.sheet-body {
  display: flex;
}

.stats-block {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 6px;
  border-right: 2px solid var(--border-subtle);
}

.stat {
  background: var(--bg-stat);
  border: 1px solid var(--border-subtle);
  border-radius: 5px;
  width: 44px;
  padding: 2px 3px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.stat-val {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.1;
}

.stat-label {
  font-size: 7px;
  font-weight: 700;
  color: var(--text-muted);
  letter-spacing: 1px;
  line-height: 1.2;
}

.stat-mod {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-mod);
  line-height: 1.1;
}

.right-panel {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 6px 8px;
}

.vitals-row {
  display: flex;
  gap: 4px;
}

.vital {
  flex: 1;
  border-radius: 5px;
  padding: 3px 2px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0px;
  margin: 0;
  border: 1px solid var(--border-subtle);
}

.vital.hp    { background: var(--bg-vital-hp); }
.vital.ac    { background: var(--bg-vital-ac); }
.vital.speed { background: var(--bg-vital-speed); }
.vital.prof  { background: var(--bg-vital-prof); }

.vital-num {
  font-size: 15px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.1;
}

.vital figcaption {
  font-size: 8px;
  font-weight: 600;
  color: var(--text-muted);
  letter-spacing: 0.6px;
  text-transform: uppercase;
}

.skills-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3px;
}

.skill {
  background: var(--bg-skill);
  border: 1px solid var(--border-subtle);
  border-radius: 4px;
  font-size: 10px;
  color: var(--text-muted);
  padding: 3px 5px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.skill.active {
  background: var(--bg-skill-active);
  color: var(--text-primary);
  border-color: var(--accent-purple);
}

.skill-bonus {
  font-weight: 700;
  color: var(--accent-teal);
  font-size: 10px;
}

.trait-row {
  display: flex;
  gap: 4px;
}

.trait {
  background: var(--bg-trait);
  border: 1px solid var(--accent-gold);
  border-radius: 20px;
  font-size: 9px;
  font-weight: 600;
  color: var(--accent-gold);
  padding: 2px 7px;
  white-space: nowrap;
}
